    def binary_to_octal(self, binary: str) -> str:
        if not binary or not binary.isdigit() or any(d not in "01" for d in binary):
            raise ValueError("Invalid binary input")

        octal = ""
        while len(binary) % 3 != 0:
            binary = "0" + binary

        for i in range(0, len(binary), 3):
            oct_digit = str(int(binary[i:i+3], base=2))
