// Given a string text, apply the following transformations:
// - If the text starts with whitespace, convert the first word to uppercase
// - If the text ends with whitespace, convert the last word to lowercase
// - If the text contains more than 2 consecutive spaces, reverse the subsequent word
// - If the text is longer than 50 characters, change spaces to underscore else, change them to dash
//
// For example:
//   enhance(" Example") => "EXAMPLE"
//   enhance("Example ") => "example"
//   enhance(" Example  1  2  3") => "EXAMPLE_1_2_3"
//   enhance("Example   word   Another   Example") => "Example DROW another example"

func enhance(text string) string {
  segs := strings.Fields(text)

  switch {
  case len(text) > 50:
    text = strings.ReplaceAll(text, " ", "_")
  default:
    text = strings.ReplaceAll(text, " ", "-")
  } 

  switch {
  case unicode.IsSpace(rune(text[0])):
    segs[0] = strings.ToUpper(segs[0])
  case unicode.IsSpace(rune(text[len(text)-1])):
    segs[len(segs)-1] = strings.ToLower(segs[len(segs)-1])
  }   

  for i, seg := range segs {
    if i != 0 && i != len(segs)-1 && len(segs[i-1]) > 2 {
      segs[i] = reverse(seg)
    } 
  }           

  return strings.Join(segs, "")
}

func reverse(input string) string {
  runes := []rune(input)
  for i, j := 0, len(runes)-1; i < j; i, j = i+1, j-1 {
    runes[i], runes[j] = runes[j], runes[i]
  }
  return string(runes)
}

