    pivot_value = l[pivot_index]
    l[high], l[pivot_index] = l[pivot_index], l[high]
    store_index = low
    for i in range(low, high):
        if cmp_func(l[i], pivot_value):
            l[store_index], l[i] = l[i], l[store_index]
            store_index += 1
    l[high], l[store_index] = l[store_index], l[high]
