public boolean isNested(String string) {
    // Initialize stack
    Stack<Character> stack = new Stack<>();

    // Iterate through characters of the string
    for (int i = 0; i < string.length(); i++) {
        char c = string.charAt(i);

        // If the character is an open bracket, push it to the stack
        if (c == '[') {
            stack.push(c);
        }

        // If the character is a close bracket
        else if (c == ']') {
            // If the stack is empty, it means there's no matching open bracket
            if (stack.isEmpty()) {
                return false;
            }

            // If the top element of the stack is an open bracket, pop it from the stack
            if (stack.peek() == '[') {
                stack.pop();
            } else {
                // If the top element is not an open bracket, it's not a valid nested sequence
                return false;
            }
        }
    }

    // If the stack is empty, it means there are no open brackets without close brackets
    int nestedBracketCount = 0;
    while (!stack.isEmpty()) {
        stack.pop();
        nestedBracketCount++;
    }

    // Return true if the number of nested brackets is at least 1
    return nestedBracketCount >= 1;
}
