class Solution {
    /**
     * Rounds a decimal number (as a string) to the nearest integer.
     * If the string represents a number halfway between two integers,
     * rounds to the integer farthest from zero.
     */
    public static int closest_integer(String value) {
        double num = Double.parseDouble(value);
        int floor = (int) Math.floor(num);
        int ceil = (int) Math.ceil(num);
        if (num - floor == 0.5){
